# kv.py —— Redis 优先，diskcache 进程外等价回退
# 教学: 同一接口 get/put/incr，两种后端

import time
from config import DISK_CACHE, REDIS_URL

class RedisKV:
    name = "redis"
    def __init__(self, url):
        import redis
        self.r = redis.Redis.from_url(
            url, socket_connect_timeout=1)
    def put(self, k, v, ttl=60):
        return self.r.setex(k, ttl, v)
    def get(self, k):
        return self.r.get(k)
    def incr(self, k, ttl=3600):
        """原子计数：API限流(每IP每时N次)"""
        return self.r.incr(k, 1)

def test_kv_roundtrip(kv):
    kv.put("k", "v"); assert kv.get("k") == "v"
def test_fallback():
    assert RedisKV.unavailable \
           or use_diskcache() is True
